@sig trait ChargingInterlockAssessor_Api {
  def id: Art.BridgeId
  def charger_evidence_Id : Art.PortId
  def charging_assessment_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var charging_assessment: Power_Propulsion_Availability_Supervisor.ChargingAssessment.Type = $

  def put_charging_assessment(value : Power_Propulsion_Availability_Supervisor.ChargingAssessment.Type) : Unit = {
    Contract(
      Modifies(charging_assessment),
      Ensures(
        charging_assessment == value
      )
    )
    Spec {
      charging_assessment = value
    }

    Art.putValue(charging_assessment_Id, Power_Propulsion_Availability_Supervisor.ChargingAssessment_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class ChargingInterlockAssessor_Initialization_Api (
  val id: Art.BridgeId,
  val charger_evidence_Id : Art.PortId,
  val charging_assessment_Id : Art.PortId) extends ChargingInterlockAssessor_Api

@datatype class ChargingInterlockAssessor_Operational_Api (
  val id: Art.BridgeId,
  val charger_evidence_Id : Art.PortId,
  val charging_assessment_Id : Art.PortId) extends ChargingInterlockAssessor_Api {

  // Logika spec var representing port state for incoming data port
  @spec var charger_evidence: Power_Propulsion_Availability_Supervisor.ChargerEvidence = $

  def get_charger_evidence() : Option[Power_Propulsion_Availability_Supervisor.ChargerEvidence] = {
    Contract(
      Ensures(
        Res == Some(charger_evidence)
      )
    )
    val value : Option[Power_Propulsion_Availability_Supervisor.ChargerEvidence] = Art.getValue(charger_evidence_Id) match {
      case Some(Power_Propulsion_Availability_Supervisor.ChargerEvidence_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port charger_evidence.  Expecting 'Power_Propulsion_Availability_Supervisor.ChargerEvidence_Payload' but received ${v}")
        None[Power_Propulsion_Availability_Supervisor.ChargerEvidence]()
      case _ => None[Power_Propulsion_Availability_Supervisor.ChargerEvidence]()
    }
    return value
  }
}
